import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"33、【遁】 艮下乾上","description":"溫公易說 - 33、【遁】 艮下乾上","frontmatter":{"title":"33、【遁】 艮下乾上","description":"溫公易說 - 33、【遁】 艮下乾上"},"headers":[],"relativePath":"classics/wengong/034.md","filePath":"classics/wengong/034.md"}'),l={name:"classics/wengong/034.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_33、【遁】-艮下乾上" tabindex="-1">33、【遁】 艮下乾上 <a class="header-anchor" href="#_33、【遁】-艮下乾上" aria-label="Permalink to “33、【遁】 艮下乾上”">​</a></h1><h3 id="彖曰-遁亨-遁而亨也。剛當位而應-與時行也。小利貞-浸而長也。遁之時義大矣哉。" tabindex="-1">彖曰：遁亨，遁而亨也。剛當位而應，與時行也。小利貞，浸而長也。遁之時義大矣哉。 <a class="header-anchor" href="#彖曰-遁亨-遁而亨也。剛當位而應-與時行也。小利貞-浸而長也。遁之時義大矣哉。" aria-label="Permalink to “彖曰：遁亨，遁而亨也。剛當位而應，與時行也。小利貞，浸而長也。遁之時義大矣哉。”">​</a></h3><h3 id="象曰-天下有山-遁。君子以遠小人-不惡而嚴。" tabindex="-1">象曰：天下有山，遁。君子以遠小人，不惡而嚴。 <a class="header-anchor" href="#象曰-天下有山-遁。君子以遠小人-不惡而嚴。" aria-label="Permalink to “象曰：天下有山，遁。君子以遠小人，不惡而嚴。”">​</a></h3><h3 id="初六-遁尾-厲-勿用有攸往-象曰-遁尾之厲-不往何災也。" tabindex="-1">初六：遁尾，厲，勿用有攸往 象曰：遁尾之厲，不往何災也。 <a class="header-anchor" href="#初六-遁尾-厲-勿用有攸往-象曰-遁尾之厲-不往何災也。" aria-label="Permalink to “初六：遁尾，厲，勿用有攸往 象曰：遁尾之厲，不往何災也。”">​</a></h3><h3 id="六二-執之用黃牛之革-莫之勝說-象曰-執用黃牛-固志也。" tabindex="-1">六二：執之用黃牛之革，莫之勝說 象曰：執用黃牛，固志也。 <a class="header-anchor" href="#六二-執之用黃牛之革-莫之勝說-象曰-執用黃牛-固志也。" aria-label="Permalink to “六二：執之用黃牛之革，莫之勝說 象曰：執用黃牛，固志也。”">​</a></h3><p>遁之為道，避內而趨外者也。二以柔居內，未得自去者也。然履中守正，和而不流，執志之堅，人不能奪，故曰執之用黃牛之革，莫之勝說。黃者中也，牛革取其柔而堅韌也。</p><h3 id="九三-系遁-有疾-厲-畜臣妾吉-象曰-系遁之厲-有疾憊也。畜臣妾吉-不可大事也。" tabindex="-1">九三：系遁，有疾，厲，畜臣妾吉 象曰：系遁之厲，有疾憊也。畜臣妾吉，不可大事也。 <a class="header-anchor" href="#九三-系遁-有疾-厲-畜臣妾吉-象曰-系遁之厲-有疾憊也。畜臣妾吉-不可大事也。" aria-label="Permalink to “九三：系遁，有疾，厲，畜臣妾吉 象曰：系遁之厲，有疾憊也。畜臣妾吉，不可大事也。”">​</a></h3><p>三以剛德居位，而宴安於內，繫於榮利，不能自退，故曰有疾。小人道長，貪位不退，危之道也，故曰厲。臣妾者，繫於人而不能自去者也，故畜臣妾吉。</p><h3 id="九四-好遁-君子吉-小人否-象曰-君子好遁-小人否也。" tabindex="-1">九四：好遁，君子吉，小人否 象曰：君子好遁，小人否也。 <a class="header-anchor" href="#九四-好遁-君子吉-小人否-象曰-君子好遁-小人否也。" aria-label="Permalink to “九四：好遁，君子吉，小人否 象曰：君子好遁，小人否也。”">​</a></h3><p>四以剛德而處非其位，君子難進而易退，小人反是者也，故曰好遁君子吉，小人否也。</p><h3 id="九五-嘉遁-貞吉-象曰-嘉遁貞吉-以正志也。" tabindex="-1">九五：嘉遁，貞吉 象曰：嘉遁貞吉，以正志也。 <a class="header-anchor" href="#九五-嘉遁-貞吉-象曰-嘉遁貞吉-以正志也。" aria-label="Permalink to “九五：嘉遁，貞吉 象曰：嘉遁貞吉，以正志也。”">​</a></h3><p>中正德之嘉也。君子邦有道則見，邦無道則隱，可以進而進，可以退而退，不失其時，以中正為心者也，故曰嘉遁貞吉。</p><h3 id="上九-肥遁-無不利-象曰-肥遁無不利-無所疑也。" tabindex="-1">上九：肥遁，無不利 象曰：肥遁無不利，無所疑也。 <a class="header-anchor" href="#上九-肥遁-無不利-象曰-肥遁無不利-無所疑也。" aria-label="Permalink to “上九：肥遁，無不利 象曰：肥遁無不利，無所疑也。”">​</a></h3>',13)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
